// Formata os dados do GSC para o relatório
const items = $input.all();
const rows = items[0].json.rows || [];

// Agrega totais
let totalClicks = 0;
let totalImpressions = 0;

rows.forEach(r => {
  totalClicks += r.clicks;
  totalImpressions += r.impressions;
});

const ctr = totalImpressions > 0 
  ? ((totalClicks / totalImpressions) * 100).toFixed(2) 
  : 0;

const avgPosition = rows.length > 0
  ? (rows.reduce((sum, r) => sum + r.position, 0) / rows.length).toFixed(1)
  : 0;

// Top 5 queries por cliques
const top5 = rows
  .sort((a, b) => b.clicks - a.clicks)
  .slice(0, 5)
  .map((r, i) => `${i+1}. "${r.keys[0]}" — ${r.clicks} cliques, pos. ${r.position.toFixed(1)}`);

return [{
  json: {
    gsc_totalClicks: totalClicks,
    gsc_totalImpressions: totalImpressions,
    gsc_ctr: ctr + '%',
    gsc_avgPosition: avgPosition,
    gsc_top5Queries: top5.join('\n'),
    gsc_periodo: `${$now.minus(7, 'days').toFormat('dd/MM')} a ${$now.minus(1, 'days').toFormat('dd/MM/yyyy')}`
  }
}];

// Formata os dados do GA4 para o relatório
const items = $input.all();
const rows = items[0].json.rows || [];

let totalSessions = 0;
let totalUsers = 0;
let bounceRateSum = 0;
let durationSum = 0;

const channelMap = {};

rows.forEach(r => {
  const channel = r.dimensionValues[0].value;
  const sessions = parseInt(r.metricValues[0].value);
  const users = parseInt(r.metricValues[1].value);
  const bounce = parseFloat(r.metricValues[2].value);
  const duration = parseFloat(r.metricValues[3].value);

  totalSessions += sessions;
  totalUsers += users;
  bounceRateSum += bounce;
  durationSum += duration;

  channelMap[channel] = `${sessions} sessões`;
});

const avgBounce = rows.length > 0 
  ? (bounceRateSum / rows.length * 100).toFixed(1) + '%'
  : '0%';

const avgDuration = rows.length > 0
  ? Math.round(durationSum / rows.length)
  : 0;

const durationFormatted = `${Math.floor(avgDuration/60)}m ${avgDuration%60}s`;

const channelLines = Object.entries(channelMap)
  .map(([k, v]) => `• ${k}: ${v}`)
  .join('\n');

return [{
  json: {
    ga4_totalSessions: totalSessions,
    ga4_totalUsers: totalUsers,
    ga4_bounceRate: avgBounce,
    ga4_avgDuration: durationFormatted,
    ga4_porCanal: channelLines
  }
}];

const input = $input.first().json;
const raw = input['json_data'] || Object.values(input)[1] || '';
let ads = {};
try {
  ads = JSON.parse(raw);
} catch(e) {
  ads = {};
}
const camp = ads.campaign || {};
return [{
  json: {
    ads_impressions: camp.impressions || 0,
    ads_clicks:      camp.clicks || 0,
    ads_ctr:         camp.ctr || '0.00',
    ads_custo:       camp.costBRL || '0.00',
    ads_cpc:         camp.avgCPC || '0.00',
    ads_conversoes:  camp.conversions || '0.0',
    ads_periodo:     (ads.period?.start || '') + ' a ' + (ads.period?.end || ''),
  }
}];

